input.query:
SELECT 'claims_2023' AS k, COUNT(*) AS v FROM claim WHERE accident_date BETWEEN '2023-01-01' AND '2023-12-31'
UNION ALL SELECT 'claims_total', COUNT(*) FROM claim
UNION ALL SELECT 'txn_types', COUNT(DISTINCT txn_type) FROM premium_txn
UNION ALL SELECT 'exposure_rows', COUNT(*) FROM premium_txn
UNION ALL SELECT 'terms', COUNT(*) FROM policy_term;
SELECT txn_type, COUNT(*), SUM(exposure_units), MIN(effective_date), MAX(effective_date) FROM premium_txn GROUP BY 1;
